/**
 * Who owns the reader's JavaScript, by module provenance. For each chunk on the
 * route's critical path: follow its `sourceMappingURL`, decode the `mappings`
 * VLQ, and attribute each run of generated bytes to the SOURCE MODULE that
 * produced it. A path under `maplibre-gl` or `mapbox-gl` is the map library;
 * everything else is not. It attributes within a chunk, so re-chunking cannot
 * move it (a whole-chunk substring test can).
 *
 * 1. **Unmapped bytes are their own bucket**, never folded into application.
 * 2. **Gzip is NOT split.** Compression is not additive across module
 *    boundaries; raw bytes are attributable, transfer bytes are reported whole.
 * 3. **A missing map is reported, never zero.** Source maps are emitted only
 *    when `WTP_ATTRIBUTION_BUILD=1` (see `next.config.ts`); without them this
 *    returns `{ available: false }`.
 */

import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";

/** Source paths that ARE the map library. Matched on the module path. */
const MAP_LIBRARY = /(?:^|[/\\])(?:maplibre-gl|mapbox-gl)(?:[/\\@]|$)/i;

const B64 = new Map(
  [..."ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"].map(
    (c, i) => [c, i],
  ),
);

/**
 * Decode one VLQ field, returning the value and the next index. Written out
 * rather than imported, because this runs postbuild with production
 * dependencies only.
 */
function decodeVlq(str, i) {
  let result = 0;
  let shift = 0;
  let cont = true;
  while (cont) {
    const digit = B64.get(str[i++]);
    if (digit === undefined) return null;
    cont = (digit & 32) !== 0;
    result += (digit & 31) << shift;
    shift += 5;
  }
  const negative = (result & 1) === 1;
  result >>>= 1;
  return { value: negative ? -result : result, next: i };
}

/**
 * Bytes of `code` attributable to each source index, from `mappings`. A
 * segment owns the bytes up to the NEXT segment's column or the end of that
 * generated line.
 *
 * Returns `{ bySource: Map<number, number>, unmapped: number }`. The two plus
 * nothing else sum to `code.length`; the caller asserts that.
 */
export function attributeChunk(code, mappings) {
  const lines = code.split("\n");
  const bySource = new Map();
  let unmapped = 0;
  let sourceIndex = 0;

  /*
   * Source map columns are UTF-16 code units and the budget is UTF-8 bytes, so
   * every span is measured with `Buffer.byteLength` and the buckets sum to the
   * byte total exactly.
   */
  const span = (line, from, to) =>
    from >= to ? 0 : Buffer.byteLength(line.slice(from, to), "utf8");

  const groups = mappings.split(";");
  for (let line = 0; line < lines.length; line++) {
    const text = lines[line];
    // `+1` for the newline that `split` removed, except on the last line.
    const newline = line < lines.length - 1 ? 1 : 0;
    const cols = text.length;
    const group = groups[line];
    if (group === undefined || group === "") {
      unmapped += span(text, 0, cols) + newline;
      continue;
    }

    // Decode this line's segments into (column, sourceIndex) pairs. `sourceIndex`
    // is delta-encoded ACROSS lines, so it is not reset per line; the generated
    // column is reset per line, which is why it is declared here.
    let column = 0;
    const segments = [];
    for (const seg of group.split(",")) {
      if (seg === "") continue;
      let i = 0;
      const col = decodeVlq(seg, i);
      if (!col) continue;
      column += col.value;
      i = col.next;
      const srcDelta = decodeVlq(seg, i);
      if (!srcDelta) {
        // A one-field segment marks generated code with NO source. Recorded as
        // a boundary owned by nobody rather than skipped, so the span before
        // the next segment is not silently credited to the previous module.
        segments.push({ column, source: null });
        continue;
      }
      sourceIndex += srcDelta.value;
      segments.push({ column, source: sourceIndex });
    }
    if (segments.length === 0) {
      unmapped += span(text, 0, cols) + newline;
      continue;
    }

    // Anything before the first segment belongs to nobody. So does the
    // newline: it is generated punctuation, not any module's code.
    unmapped += span(text, 0, Math.min(segments[0].column, cols)) + newline;
    for (let s = 0; s < segments.length; s++) {
      const start = Math.min(segments[s].column, cols);
      const end = Math.min(
        s + 1 < segments.length ? segments[s + 1].column : cols,
        cols,
      );
      const bytes = span(text, start, end);
      if (segments[s].source === null) unmapped += bytes;
      else
        bySource.set(
          segments[s].source,
          (bySource.get(segments[s].source) ?? 0) + bytes,
        );
    }
  }

  return { bySource, unmapped };
}

/** The map a chunk names in its own `sourceMappingURL` comment, or null. */
function mapFor(chunkPath, code) {
  const match = /\/\/#\s*sourceMappingURL=([^\s*]+)\s*$/m.exec(code);
  if (!match) return null;
  const mapPath = join(dirname(chunkPath), match[1]);
  return existsSync(mapPath) ? mapPath : null;
}

/**
 * Attribute a route's initial JavaScript by module provenance. `srcs` are the
 * same script sources the byte total is measured from, so the split and the
 * total always describe the same files.
 */
export function attributeByProvenance({ next, srcs }) {
  let mapLibrary = 0;
  let application = 0;
  let unmapped = 0;
  let total = 0;
  let chunksWithMaps = 0;

  for (const src of srcs) {
    const file = join(next, src.replace(/^\/_next\//, ""));
    if (!existsSync(file)) continue;
    const code = readFileSync(file, "utf8");
    total += Buffer.byteLength(code);

    const mapPath = mapFor(file, code);
    if (!mapPath) {
      // No map for this chunk: its bytes are unattributed, and saying so is
      // the whole point. They are never assumed to be application code.
      unmapped += Buffer.byteLength(code);
      continue;
    }
    chunksWithMaps += 1;

    const map = JSON.parse(readFileSync(mapPath, "utf8"));
    const sources = map.sources ?? [];
    const { bySource, unmapped: chunkUnmapped } = attributeChunk(
      code,
      map.mappings ?? "",
    );
    unmapped += chunkUnmapped;
    for (const [index, bytes] of bySource) {
      const path = sources[index] ?? "";
      if (MAP_LIBRARY.test(path)) mapLibrary += bytes;
      else application += bytes;
    }
  }

  if (chunksWithMaps === 0) {
    return {
      available: false,
      why:
        "no chunk on this route carries a sourceMappingURL — rebuild with " +
        "WTP_ATTRIBUTION_BUILD=1 to emit source maps",
    };
  }

  /*
   * The three buckets and the total must agree to the byte; if not, this
   * throws rather than printing a plausible figure.
   */
  const summed = mapLibrary + application + unmapped;
  if (summed !== total) {
    throw new Error(
      `client attribution does not reconcile: ${mapLibrary} + ${application} + ` +
        `${unmapped} = ${summed}, but the chunks are ${total} bytes ` +
        `(${total - summed} unaccounted)`,
    );
  }

  return {
    available: true,
    chunksWithMaps,
    chunksTotal: srcs.length,
    total,
    mapLibrary,
    application,
    unmapped,
  };
}
